import React, { useMemo } from 'react';

// Hoisted constants: prevent new object refs every render
const AMBIENT_GLOW_LEFT_STYLE = {
  background: 'radial-gradient(circle, rgba(255, 122, 69, 0.25) 0%, transparent 70%)',
  transform: 'translateZ(0)',
};
const AMBIENT_GLOW_RIGHT_STYLE = {
  background: 'radial-gradient(circle, rgba(232, 184, 75, 0.2) 0%, transparent 70%)',
  transform: 'translateZ(0)',
};

export const FloatingDecorations = React.memo(({ isRakhiTied = false }) => {
  const elements = useMemo(() => {
    // 8 optimized floral particles for flawless 60fps performance on all devices
    return [
      { id: 1, x: 8, size: 22, duration: 14, delay: 0, type: 'marigold' },
      { id: 2, x: 22, size: 18, duration: 18, delay: 4, type: 'rosePetal' },
      { id: 3, x: 38, size: 14, duration: 12, delay: 2, type: 'sparkle' },
      { id: 4, x: 55, size: 24, duration: 16, delay: 6, type: 'marigold' },
      { id: 5, x: 70, size: 19, duration: 15, delay: 1, type: 'rosePetal' },
      { id: 6, x: 86, size: 15, duration: 13, delay: 5, type: 'sparkle' },
      { id: 7, x: 48, size: 20, duration: 17, delay: 8, type: 'rosePetal' },
      { id: 8, x: 92, size: 22, duration: 19, delay: 3, type: 'marigold' },
    ];
  }, []);

  return (
    <div
      className={`fixed inset-0 pointer-events-none overflow-hidden z-0 ${
        isRakhiTied ? 'app-color-reveal' : 'app-grayscale'
      }`}
      aria-hidden="true"
    >
      {/* Dynamic Keyframes injected for GPU compositor thread execution */}
      <style>{`
        @keyframes floatDownGpu {
          0% {
            transform: translate3d(0, -10vh, 0) rotate(0deg);
            opacity: 0;
          }
          10% {
            opacity: 0.7;
          }
          90% {
            opacity: 0.7;
          }
          100% {
            transform: translate3d(20px, 112vh, 0) rotate(360deg);
            opacity: 0;
          }
        }
        @keyframes sparklePulseGpu {
          0%, 100% {
            transform: translate3d(0, 0, 0) scale(0.7) rotate(0deg);
            opacity: 0.3;
          }
          50% {
            transform: translate3d(0, 0, 0) scale(1.2) rotate(180deg);
            opacity: 0.9;
          }
        }
      `}</style>

      {elements.map((el) => {
        if (el.type === 'marigold') {
          return (
            <div
              key={el.id}
              className="absolute select-none"
              style={{
                left: `${el.x}%`,
                top: 0,
                width: `${el.size}px`,
                height: `${el.size}px`,
                animation: `floatDownGpu ${el.duration}s linear ${el.delay}s infinite`,
                willChange: 'transform',
                transform: 'translateZ(0)',
              }}
            >
              <svg viewBox="0 0 30 30" fill="none" className="w-full h-full opacity-70">
                <circle cx="15" cy="15" r="5" fill="#B4283C" />
                {[0, 45, 90, 135, 180, 225, 270, 315].map((deg) => (
                  <ellipse
                    key={deg}
                    cx="15"
                    cy="6"
                    rx="3.5"
                    ry="6"
                    transform={`rotate(${deg} 15 15)`}
                    fill="#FF7A45"
                    stroke="#E8B84B"
                    strokeWidth="0.5"
                  />
                ))}
              </svg>
            </div>
          );
        }

        if (el.type === 'rosePetal') {
          return (
            <div
              key={el.id}
              className="absolute select-none"
              style={{
                left: `${el.x}%`,
                top: 0,
                width: `${el.size}px`,
                height: `${el.size + 4}px`,
                animation: `floatDownGpu ${el.duration}s linear ${el.delay}s infinite`,
                willChange: 'transform',
                transform: 'translateZ(0)',
              }}
            >
              <svg viewBox="0 0 20 26" fill="none" className="w-full h-full opacity-65">
                <path
                  d="M10 2 C16 4, 19 12, 16 20 C13 25, 7 25, 4 20 C1 12, 4 4, 10 2 Z"
                  fill="#B4283C"
                  stroke="#FF7A45"
                  strokeWidth="0.8"
                />
              </svg>
            </div>
          );
        }

        return (
          <div
            key={el.id}
            className="absolute select-none text-[#E8B84B]"
            style={{
              left: `${el.x}%`,
              top: `${(el.id * 14 + 10) % 85}%`,
              width: `${el.size}px`,
              height: `${el.size}px`,
              animation: `sparklePulseGpu ${el.duration / 2.5}s ease-in-out ${el.delay}s infinite`,
              willChange: 'transform, opacity',
              transform: 'translateZ(0)',
            }}
          >
            <svg viewBox="0 0 24 24" fill="currentColor" className="w-full h-full text-[#E8B84B] opacity-80">
              <path d="M12 0L14.5 9.5L24 12L14.5 14.5L12 24L9.5 14.5L0 12L9.5 9.5L12 0Z" />
            </svg>
          </div>
        );
      })}

      {/* Ambient warm radial glow in background - pre-blurred GPU gradients */}
      <div
        className="absolute top-1/4 left-1/5 w-72 h-72 rounded-full pointer-events-none opacity-40"
        style={AMBIENT_GLOW_LEFT_STYLE}
      />
      <div
        className="absolute top-2/3 right-1/4 w-80 h-80 rounded-full pointer-events-none opacity-30"
        style={AMBIENT_GLOW_RIGHT_STYLE}
      />
    </div>
  );
});