import { useEffect, useRef, useCallback } from 'react';

/**
 * Headless Audio Engine: Auto-plays sitar melody when isRakhiTied becomes true.
 * No UI — no pause button, no toggle. Music plays continuously after Rakhi is tied.
 */
export const AudioPlayer = ({ isRakhiTied }) => {
  const audioCtxRef = useRef(null);
  const intervalRef = useRef(null);
  const hasStartedRef = useRef(false);

  // Soothing festive Raag notes (frequencies in Hz: Sa, Re, Ga, Pa, Dha, Sa')
  const ragaNotes = useRef([
    261.63, // C4 (Sa)
    293.66, // D4 (Re)
    329.63, // E4 (Ga)
    392.00, // G4 (Pa)
    440.00, // A4 (Dha)
    523.25, // C5 (Sa')
    587.33, // D5 (Re')
    659.25  // E5 (Ga')
  ]);

  const playFestivePluck = useCallback((freq, duration = 1.4, timeOffset = 0) => {
    if (!audioCtxRef.current) return;
    const ctx = audioCtxRef.current;
    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const now = ctx.currentTime + timeOffset;
    const osc = ctx.createOscillator();
    const subOsc = ctx.createOscillator();
    const gainNode = ctx.createGain();
    const filter = ctx.createBiquadFilter();

    // Sitar / Santoor harmonic overtone resonance
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(freq, now);

    subOsc.type = 'sine';
    subOsc.frequency.setValueAtTime(freq * 2.01, now);

    // Warm filter for traditional Indian string feel
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(1400, now);
    filter.frequency.exponentialRampToValueAtTime(300, now + duration);

    // Gentle pluck envelope
    gainNode.gain.setValueAtTime(0.001, now);
    gainNode.gain.linearRampToValueAtTime(0.12, now + 0.04);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    osc.connect(filter);
    subOsc.connect(filter);
    filter.connect(gainNode);
    gainNode.connect(ctx.destination);

    osc.start(now);
    subOsc.start(now);
    osc.stop(now + duration);
    subOsc.stop(now + duration);
  }, []);

  const startFestiveMelody = useCallback(() => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (audioCtxRef.current.state === 'suspended') {
      audioCtxRef.current.resume();
    }

    // Melodic sequence pattern
    const melodyPattern = [
      [0, 2, 4],
      [4, 5, 7],
      [5, 4, 2],
      [2, 0, 4],
      [0, 4, 7],
      [5, 3, 0],
    ];

    let patternIdx = 0;
    const notes = ragaNotes.current;

    const tick = () => {
      const currentChord = melodyPattern[patternIdx % melodyPattern.length];
      currentChord.forEach((noteIdx, i) => {
        playFestivePluck(notes[noteIdx % notes.length], 2.2, i * 0.35);
      });
      // Add subtle drone baseline
      playFestivePluck(130.81, 3.5, 0); // Low C drone
      patternIdx++;
    };

    tick();
    intervalRef.current = setInterval(tick, 2400);
  }, [playFestivePluck]);

  // Auto-play when isRakhiTied transitions to true
  useEffect(() => {
    if (isRakhiTied && !hasStartedRef.current) {
      hasStartedRef.current = true;
      // Small delay to let the celebration confetti/bell play first
      const timer = setTimeout(() => {
        startFestiveMelody();
      }, 800);
      return () => clearTimeout(timer);
    }
  }, [isRakhiTied, startFestiveMelody]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      if (audioCtxRef.current) {
        audioCtxRef.current.close();
      }
    };
  }, []);

  // Headless — no UI rendered
  return null;
};
