import React, { useEffect, useRef, useState } from 'react';

/**
 * Thread & Glass System: Foundational GlassPanel component
 * Reinterprets glassmorphism through Indian festival materiality.
 * - Translucent warm amber/rose tint (never cool white/blue)
 * - Silk/fabric grain texture (SVG noise filter) inside blur
 * - Thin 1px gold-foil edge: border 1px solid rgba(255, 215, 120, 0.35)
 * - Layered radial diya glow behind panel (diya flame color) pulsing slowly
 * - Gold embroidery/mehendi squiggles tracing panel edges/corners
 *
 * Performance:
 * - liveGlow=false renders the glow as a static pre-blurred radial-gradient background (no live blur).
 * - Backdrop-filter is only active while the panel intersects the viewport (IntersectionObserver);
 *   off-screen panels fall back to a flat semi-transparent fill.
 */

// Hoisted constant: prevents re-creating this object on every render
const SPECULAR_SHEEN_STYLE = {
  background: 'linear-gradient(180deg, rgba(255, 255, 255, 0.16) 0%, rgba(255, 255, 255, 0.03) 65%, transparent 100%)',
};

export const GlassPanel = React.memo(({
  children,
  className = '',
  variant = 'default', // 'default' | 'rose' | 'ledger'
  stitchBorder = true,
  mehendiTrim = true,
  glowPosition = 'center',
  liveGlow = true,
  onClick,
  style = {},
  ...props
}) => {
  const panelRef = useRef(null);
  const [isInViewport, setIsInViewport] = useState(true);

  // Track viewport intersection to toggle expensive backdrop-filter on/off
  useEffect(() => {
    const currentPanel = panelRef.current;
    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsInViewport(entry.isIntersecting);
      },
      { rootMargin: '50px' }
    );

    if (currentPanel) {
      observer.observe(currentPanel);
    }

    return () => {
      if (currentPanel) {
        observer.unobserve(currentPanel);
      }
    };
  }, []);

  // Determine variant CSS class
  const variantClass =
    variant === 'rose'
      ? 'warm-glass-rose'
      : variant === 'ledger'
        ? 'warm-glass-ledger'
        : 'warm-glass-panel';

  // Glow position mapping
  const glowStyleMap = {
    center: 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-3/4 h-3/4',
    'top-right': 'top-0 right-0 w-2/3 h-2/3',
    'bottom-left': 'bottom-0 left-0 w-2/3 h-2/3',
    bottom: 'bottom-0 left-1/2 -translate-x-1/2 w-4/5 h-1/2',
  };

  return (
    <div
      ref={panelRef}
      onClick={onClick}
      style={style}
      className={`relative rounded-3xl p-6 sm:p-8 ${variantClass} ${isInViewport ? '' : 'glass-no-backdrop'
        } ${className}`}
      {...props}
    >
      {/* Static Liquid Refraction Layer: mirrors the fixed .app-background via
          background-attachment: fixed so it lines up with what's actually
          behind the panel, then distorts that static copy with the SVG
          filter instead of live backdrop-filter. Since the input never
          changes, the browser rasterizes this once and reuses it — same
          warp, none of the per-frame recompositing cost. */}
      <div className="liquid-refraction-layer" aria-hidden="true" />

      {/* Background Diya Radial Glow (Lit from within the scene) */}
      <div
        className={`diya-light-layer ${glowStyleMap[glowPosition] || glowStyleMap.center} ${liveGlow ? 'diya-glow-live' : 'diya-glow-static'
          }`}
        aria-hidden="true"
      />

      {/* Fluid Glass Specular Sheen Arc (Top-Left Liquid Glare) */}
      <div
        className="absolute top-0 left-0 right-0 h-1/2 pointer-events-none rounded-t-3xl z-0"
        style={SPECULAR_SHEEN_STYLE}
        aria-hidden="true"
      />

      {/* Silk / Fabric Grain Texture Filter */}
      <div className="silk-grain-overlay" aria-hidden="true" />

      {/* Gold Thread / Embroidery Stitch Line */}
      {stitchBorder && <div className="thread-stitch-line" aria-hidden="true" />}

      {/* Mehendi / Gota-patti Embroidery Linework Corner Accents */}
      {mehendiTrim && (
        <>
          {/* Top Left Gota Corner */}
          <svg
            className="absolute top-2 left-2 w-7 h-7 text-[#E8B84B]/60 pointer-events-none z-10"
            viewBox="0 0 30 30"
            fill="none"
          >
            <path
              d="M2 15 C 2 6, 6 2, 15 2 M 6 6 C 10 10, 10 10, 6 6 M 2 2 L 8 2 M 2 2 L 2 8"
              stroke="currentColor"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <circle cx="15" cy="2" r="1.5" fill="currentColor" />
            <circle cx="2" cy="15" r="1.5" fill="currentColor" />
          </svg>

          {/* Top Right Gota Corner */}
          <svg
            className="absolute top-2 right-2 w-7 h-7 text-[#E8B84B]/60 pointer-events-none z-10"
            viewBox="0 0 30 30"
            fill="none"
          >
            <path
              d="M28 15 C 28 6, 24 2, 15 2 M 24 6 C 20 10, 20 10, 24 6 M 28 2 L 22 2 M 28 2 L 28 8"
              stroke="currentColor"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <circle cx="15" cy="2" r="1.5" fill="currentColor" />
            <circle cx="28" cy="15" r="1.5" fill="currentColor" />
          </svg>

          {/* Bottom Left Gota Corner */}
          <svg
            className="absolute bottom-2 left-2 w-7 h-7 text-[#E8B84B]/60 pointer-events-none z-10"
            viewBox="0 0 30 30"
            fill="none"
          >
            <path
              d="M2 15 C 2 24, 6 28, 15 28 M 6 24 C 10 20, 10 20, 6 24 M 2 28 L 8 28 M 2 28 L 2 22"
              stroke="currentColor"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <circle cx="15" cy="28" r="1.5" fill="currentColor" />
            <circle cx="2" cy="15" r="1.5" fill="currentColor" />
          </svg>

          {/* Bottom Right Gota Corner */}
          <svg
            className="absolute bottom-2 right-2 w-7 h-7 text-[#E8B84B]/60 pointer-events-none z-10"
            viewBox="0 0 30 30"
            fill="none"
          >
            <path
              d="M28 15 C 28 24, 24 28, 15 28 M 24 24 C 20 20, 20 20, 24 24 M 28 28 L 22 28 M 28 28 L 28 22"
              stroke="currentColor"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <circle cx="15" cy="28" r="1.5" fill="currentColor" />
            <circle cx="28" cy="15" r="1.5" fill="currentColor" />
          </svg>
        </>
      )}

      {/* Main Content Container */}
      <div className="relative z-10 text-[#FDF3E7]">{children}</div>
    </div>
  );
});