import React, { useState, useCallback, Suspense, lazy } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FloatingDecorations } from './components/FloatingDecorations';
import { Navbar } from './components/Navbar';
import { AudioPlayer } from './components/AudioPlayer';
import { VirtualThali } from './components/VirtualThali';
import { ThreadMotif } from './components/ThreadMotif';
import { GlassPanel } from './components/GlassPanel';
import { Lock, Unlock, ArrowDown } from 'lucide-react';

// Code-split below-the-fold unlocked sections for smaller initial bundle
const SisterTaxCalculator = lazy(() =>
  import('./components/SisterTaxCalculator').then(m => ({ default: m.SisterTaxCalculator }))
);
const SisterLetter = lazy(() =>
  import('./components/SisterLetter').then(m => ({ default: m.SisterLetter }))
);

// Hoisted motion constants to prevent re-allocation
const UNLOCKED_INITIAL = { opacity: 0, y: 50 };
const UNLOCKED_ANIMATE = { opacity: 1, y: 0 };
const UNLOCKED_TRANSITION = { duration: 1, ease: 'easeOut' };

function App() {
  const [isRakhiTied, setIsRakhiTied] = useState(false);

  const handleTieRakhi = useCallback(() => {
    setIsRakhiTied(true);
  }, []);

  const grayscaleClass = isRakhiTied ? 'app-color-reveal' : 'app-grayscale';

  return (
    <div className="min-h-screen relative overflow-x-hidden flex flex-col justify-between selection:bg-[#FF7A45] selection:text-[#1a0f0f]">
      {/* Pinned Static Background Layer (Fixed to viewport for smooth glass refraction on scroll) */}
      <div className="app-background" aria-hidden="true" />

      {/* Headless Audio Engine: auto-plays sitar melody on tie */}
      <AudioPlayer isRakhiTied={isRakhiTied} />

      {/* Continuous Mauli Thread SVG Background Motif */}
      <ThreadMotif isRakhiTied={isRakhiTied} />

      {/* Dynamic Floating Marigold Petals & Diya Embers */}
      <FloatingDecorations isRakhiTied={isRakhiTied} />

      {/* Top Fixed Header with Navigation */}
      <div className={grayscaleClass}>
        <Navbar isRakhiTied={isRakhiTied} />
      </div>

      {/* Main Content Area */}
      <main className="flex-grow relative z-10 pb-12">
        {/* Hero & Virtual Rakhi Puja Thali Section */}
        <VirtualThali isRakhiTied={isRakhiTied} onTieRakhi={handleTieRakhi} />

        {/* Dynamic Unlock Banner */}
        {!isRakhiTied && (
          <div className={`max-w-xl mx-auto px-4 my-8 text-center ${grayscaleClass}`}>
            <GlassPanel variant="ledger" stitchBorder={true} mehendiTrim={false} className="p-5 flex flex-col items-center gap-2">
              <div className="flex items-center gap-2 text-[#E8B84B] font-semibold text-sm">
                <Lock className="w-4 h-4 text-[#FF7A45]" />
                <span>Page Sections Locked</span>
              </div>
              <p className="text-xs text-[#FDF3E7]/80">
                Drag or tie the Rakhi on the wrist above to unlock the Sister Tax Shagun Envelope and your Sacred Letter!
              </p>
            </GlassPanel>
          </div>
        )}

        {/* Smoothly Unlocked Sections */}
        <AnimatePresence>
          {isRakhiTied && (
            <motion.div
              initial={UNLOCKED_INITIAL}
              animate={UNLOCKED_ANIMATE}
              transition={UNLOCKED_TRANSITION}
              className="space-y-12"
            >
              {/* Unlocked Celebration Banner */}
              <div className="max-w-4xl mx-auto px-4">
                <GlassPanel variant="default" stitchBorder={true} mehendiTrim={false} className="p-4 flex items-center justify-between shadow-coral-glow">
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-xl bg-[#E8B84B] text-[#1a0f0f] font-bold">
                      <Unlock className="w-5 h-5" />
                    </div>
                    <div>
                      <h4 className="text-sm font-bold text-[#E8B84B]">
                        Sacred Bond Sealed
                      </h4>
                      <p className="text-xs text-[#FDF3E7]/80">
                        Explore the Shagun Ledger and Sister's Letter below.
                      </p>
                    </div>
                  </div>
                  <a
                    href="#sister-tax"
                    className="hidden sm:inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full bg-gradient-to-r from-[#FF7A45] to-[#E8B84B] text-[#1a0f0f] text-xs font-bold transition-all shadow-md"
                  >
                    <span>Pay Shagun</span>
                    <ArrowDown className="w-3.5 h-3.5" />
                  </a>
                </GlassPanel>
              </div>

              {/* Sibling Tax / Shagun Calculator Section */}
              <Suspense fallback={null}>
                <SisterTaxCalculator />
                <SisterLetter />
              </Suspense>
            </motion.div>
          )}
        </AnimatePresence>
      </main>
    </div>
  );
}

if (typeof window !== 'undefined' && typeof navigator !== 'undefined') {
  const isLowEnd =
    (navigator.deviceMemory !== undefined && navigator.deviceMemory <= 4) ||
    (navigator.hardwareConcurrency !== undefined && navigator.hardwareConcurrency <= 4) ||
    (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

  if (isLowEnd) {
    document.documentElement.classList.add('glass-lite');
  }
}


export default App;
